mapper.select:
SELECT o.id AS id, o.order_no AS orderNo, o.scope_type AS scopeType, o.scope_desc AS scopeDesc, o.status AS status, o.checker_name AS checkerName, o.start_time AS startTime, o.base_time AS baseTime, o.item_count AS itemCount, (SELECT COUNT(*) FROM stock_check_item i WHERE i.order_id = o.id AND i.actual_qty IS NOT NULL) AS enteredCount, (SELECT COUNT(*) FROM stock_check_item i WHERE i.order_id = o.id AND i.diff_qty IS NOT NULL AND i.diff_qty <> 0) AS diffCount, o.surplus_amount AS surplusAmount, o.shortage_amount AS shortageAmount, o.during_change_count AS duringChangeCount, o.auditor_name AS auditorName, o.audit_time AS auditTime, o.audit_remark AS auditRemark, o.cancel_reason AS cancelReason, o.create_time AS createTime FROM stock_check_order o
AND o.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND o.status = #{q.status}
AND o.checker_name LIKE CONCAT('%', #{q.checkerName}, '%')
AND o.auditor_name LIKE CONCAT('%', #{q.auditorName}, '%')
AND o.create_time >= #{beginTime}
AND o.create_time < #{endTime}
ORDER BY o.create_time DESC, o.id DESC
